import React from "react";
import type { StickerProps } from "../../types";
import { AnimatedSticker } from "../../components/AnimatedSticker";

// Exact reference pixels embedded as a lossless PNG — same technique as CatbeatsSticker.
const IMAGE = "data:image/png;base64,";

/**
 * Spooky Witch Sticker — reproduced from the original Dribbble reference artwork.
 * Text, if any, is baked into the artwork and is not configurable.
 */
export const SpookyWitchSticker: React.FC<StickerProps> = (props) => (
  <AnimatedSticker
    {...props}
    label="Spooky Witch Sticker"
    viewBox="0 0 320 307"
    motion="tilt"
    duration={3.4}
    origin="160px 307px"
  >
    <image href={IMAGE} x={0} y={0} width={320} height={307} />
  </AnimatedSticker>
);

export default SpookyWitchSticker;
